/**
 * Position-uncertainty golden: the TS port of positionUncertainty must return
 * the same model bound, bound span, delta-T sigma, and clock term as the
 * Python reference for each body and instant in uncertainty-golden.json
 * (generated by python/export_uncertainty_golden.py), and must fail where the
 * reference has no data for a body.
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { Engine } from "../src/chart.js";
import { loadNodeData } from "../src/node-loader.js";
import { positionUncertainty } from "../src/uncertainty.js";

const here = dirname(fileURLToPath(import.meta.url));
const G = JSON.parse(readFileSync(join(here, "../../test/uncertainty-golden.json"), "utf8"));
const eng = new Engine(loadNodeData(join(here, "../../data"), "embedded", "full"));

let checks = 0;
let failures = 0;
const ok = (cond: boolean, msg: string): void => {
  checks++;
  if (!cond) { failures++; console.error(`FAIL ${msg}`); }
};

// eslint-disable-next-line @typescript-eslint/no-explicit-any
for (const c of G.cases as any[]) {
  let got = null;
  try {
    got = positionUncertainty(eng, c.body, c.jd, { zodiac: c.zodiac });
  } catch (e) {
    if (!(e instanceof RangeError)) throw e;
  }
  const want = c.result;
  ok((got === null) === (want === null), `${c.id}: computed in one engine and not the other`);
  if (!got || !want) continue;
  ok(got.modelBoundArcsec === want.model_bound_arcsec,
    `${c.id}: bound ${got.modelBoundArcsec} vs ${want.model_bound_arcsec}`);
  ok(JSON.stringify(got.boundSpan) === JSON.stringify(want.bound_span), `${c.id}: bound span`);
  ok(Math.abs(got.deltaTSigmaSeconds - want.delta_t_sigma_seconds) < 1e-9, `${c.id}: delta-T sigma`);
  ok(Math.abs(got.speed - want.speed) < 1e-9, `${c.id}: speed ${got.speed} vs ${want.speed}`);
  ok(Math.abs(got.clockSigmaArcsec - want.clock_sigma_arcsec) < 1e-6,
    `${c.id}: clock term ${got.clockSigmaArcsec} vs ${want.clock_sigma_arcsec}`);
}

// The shape of the answer, stated as facts a reader would rely on.
{
  const j2000 = 2451545.0;
  const moon = positionUncertainty(eng, "moon", j2000);
  ok(moon.modelBoundArcsec === 3 && moon.clockSigmaArcsec < 0.1, "a modern Moon: bound 3 arcsec, clock term negligible");
  const old = positionUncertainty(eng, "moon", 1757600.0); // about 100 CE
  ok(old.modelBoundArcsec === null && old.clockSigmaArcsec > 60, "an ancient Moon: no bound claimed, clock term over an arcminute");
  const saturn = positionUncertainty(eng, "saturn", 1757600.0);
  ok(saturn.clockSigmaArcsec < 1, "ancient Saturn barely notices the clock");
  ok(positionUncertainty(eng, "true_node", j2000).modelBoundArcsec === 60, "the true node's bound is one arcminute");
}

console.log(`${checks} checks, ${failures} failures`);
process.exit(failures === 0 ? 0 : 1);
